//! Creature sprite sheets. Generated by `tools/make_creatures.py` from the
//! creature kits' manifests in `art/kits`; do not edit.

use zrpg_core::EnemyKind;

use crate::enemies::{Clip, Sheet};

/// From `art/kits/undead-four-direction-v1/art/extracted/manifest.json`.
pub const UNDEAD: Sheet = Sheet {
    png: include_bytes!("../assets/creatures/undead.png"),
    height: 0.95,
    body_px: 61.5,
    locomotion: Clip {
        name: "walk",
        fps: 8.0,
        hit: None,
    },
    attacks: [
        Clip {
            name: "claw_swipe",
            fps: 10.0,
            hit: Some(3),
        },
        Clip {
            name: "lunge",
            fps: 10.0,
            hit: Some(3),
        },
        Clip {
            name: "two_hand_slam",
            fps: 8.0,
            hit: Some(4),
        },
    ],
};

/// The animated sheet for a kind, if it has one (the zombie is a still).
pub fn sheet(kind: EnemyKind) -> Option<&'static Sheet> {
    match kind {
        EnemyKind::Undead => Some(&UNDEAD),
        _ => None,
    }
}
